-- field: allPlaces
SELECT json_build_object('nodes', coalesce(json_agg(__s_3.ndata ORDER BY __s_3.__rn ASC) FILTER (WHERE __s_3.__rn <= $1), '[]'::json)) AS data
FROM (
  SELECT json_build_object('centroid', (SELECT CASE WHEN (__geo.j->>'type') IN ('Point', 'LineString', 'Polygon', 'MultiPoint', 'MultiLineString', 'MultiPolygon', 'GeometryCollection') THEN CASE WHEN 'Geometry' || (__geo.j->>'type') || __geo.dims IN ('GeometryPoint') THEN CASE WHEN json_array_length(__geo.j->'coordinates') = 0 THEN NULL ELSE json_build_object('__typename', 'Geometry' || (__geo.j->>'type') || __geo.dims, 'srid', __geo.srid, 'x', __geo.j->'coordinates'->0, 'y', __geo.j->'coordinates'->1) END WHEN 'Geometry' || (__geo.j->>'type') || __geo.dims IN ('GeometryPointM', 'GeometryPointZ', 'GeometryPointZM') THEN CASE WHEN json_array_length(__geo.j->'coordinates') = 0 THEN NULL ELSE json_build_object('__typename', 'Geometry' || (__geo.j->>'type') || __geo.dims, 'srid', __geo.srid) END ELSE json_build_object('__typename', 'Geometry' || (__geo.j->>'type') || __geo.dims, 'srid', __geo.srid) END END FROM (SELECT ST_AsGeoJSON(__geo_v.g)::json AS j, ST_SRID(__geo_v.g) AS srid, CASE ST_Zmflag(__geo_v.g::geometry) WHEN 1 THEN 'M' WHEN 2 THEN 'Z' WHEN 3 THEN 'ZM' ELSE '' END AS dims FROM (SELECT "public"."places_centroid"("p" => ROW(__t_1."id", __t_1."owner_id", __t_1."name", __t_1."location", __t_1."area")::"public"."places") AS g) AS __geo_v) AS __geo WHERE __geo.j IS NOT NULL), 'outline', (SELECT coalesce(json_agg((SELECT CASE WHEN (__geo.j->>'type') IN ('Point', 'LineString', 'Polygon', 'MultiPoint', 'MultiLineString', 'MultiPolygon', 'GeometryCollection') THEN CASE WHEN 'Geometry' || (__geo.j->>'type') || __geo.dims IN ('GeometryPoint', 'GeometryPointM', 'GeometryPointZ', 'GeometryPointZM') THEN CASE WHEN json_array_length(__geo.j->'coordinates') = 0 THEN NULL ELSE json_build_object('__typename', 'Geometry' || (__geo.j->>'type') || __geo.dims, 'geojson', __geo.j) END ELSE json_build_object('__typename', 'Geometry' || (__geo.j->>'type') || __geo.dims, 'geojson', __geo.j) END END FROM (SELECT ST_AsGeoJSON(__geo_v.g)::json AS j, ST_SRID(__geo_v.g) AS srid, CASE ST_Zmflag(__geo_v.g::geometry) WHEN 1 THEN 'M' WHEN 2 THEN 'Z' WHEN 3 THEN 'ZM' ELSE '' END AS dims FROM (SELECT __v_2.v AS g) AS __geo_v) AS __geo WHERE __geo.j IS NOT NULL)), '[]'::json) FROM (SELECT * FROM "public"."places_outline"("p" => ROW(__t_1."id", __t_1."owner_id", __t_1."name", __t_1."location", __t_1."area")::"public"."places") AS __v_2(v) LIMIT 100) AS __v_2)) AS ndata, row_number() OVER (ORDER BY __t_1."id" ASC) AS __rn
  FROM "public"."places" AS __t_1
  ORDER BY __t_1."id" ASC
  LIMIT 101
) AS __s_3
GROUP BY ()
-- args: [100]

-- field: makePoint
SELECT (SELECT CASE WHEN (__geo.j->>'type') IN ('Point', 'LineString', 'Polygon', 'MultiPoint', 'MultiLineString', 'MultiPolygon', 'GeometryCollection') THEN CASE WHEN 'Geometry' || (__geo.j->>'type') || __geo.dims IN ('GeometryPoint') THEN CASE WHEN json_array_length(__geo.j->'coordinates') = 0 THEN NULL ELSE json_build_object('__typename', 'Geometry' || (__geo.j->>'type') || __geo.dims, 'x', __geo.j->'coordinates'->0, 'y', __geo.j->'coordinates'->1) END WHEN 'Geometry' || (__geo.j->>'type') || __geo.dims IN ('GeometryPointZ') THEN CASE WHEN json_array_length(__geo.j->'coordinates') = 0 THEN NULL ELSE json_build_object('__typename', 'Geometry' || (__geo.j->>'type') || __geo.dims, 'x', __geo.j->'coordinates'->0, 'y', __geo.j->'coordinates'->1, 'z', __geo.j->'coordinates'->2) END WHEN 'Geometry' || (__geo.j->>'type') || __geo.dims IN ('GeometryPointM', 'GeometryPointZM') THEN CASE WHEN json_array_length(__geo.j->'coordinates') = 0 THEN NULL ELSE json_build_object('__typename', 'Geometry' || (__geo.j->>'type') || __geo.dims) END ELSE json_build_object('__typename', 'Geometry' || (__geo.j->>'type') || __geo.dims) END END FROM (SELECT ST_AsGeoJSON(__geo_v.g)::json AS j, ST_SRID(__geo_v.g) AS srid, CASE ST_Zmflag(__geo_v.g::geometry) WHEN 1 THEN 'M' WHEN 2 THEN 'Z' WHEN 3 THEN 'ZM' ELSE '' END AS dims FROM (SELECT __fn.v AS g) AS __geo_v) AS __geo WHERE __geo.j IS NOT NULL) AS data FROM (SELECT "public"."make_point"("x" => $1::"pg_catalog"."float8", "y" => $2::"pg_catalog"."float8") AS v) AS __fn
-- args: [1,2]

-- field: gridPoints
SELECT coalesce(json_agg((SELECT CASE WHEN (__geo.j->>'type') IN ('Point', 'LineString', 'Polygon', 'MultiPoint', 'MultiLineString', 'MultiPolygon', 'GeometryCollection') THEN CASE WHEN 'Geography' || (__geo.j->>'type') || __geo.dims IN ('GeographyPoint') THEN CASE WHEN json_array_length(__geo.j->'coordinates') = 0 THEN NULL ELSE json_build_object('longitude', __geo.j->'coordinates'->0, 'latitude', __geo.j->'coordinates'->1) END WHEN 'Geography' || (__geo.j->>'type') || __geo.dims IN ('GeographyPointM', 'GeographyPointZ', 'GeographyPointZM') THEN CASE WHEN json_array_length(__geo.j->'coordinates') = 0 THEN NULL ELSE '{}'::json END ELSE '{}'::json END END FROM (SELECT ST_AsGeoJSON(__geo_v.g)::json AS j, ST_SRID(__geo_v.g) AS srid, CASE ST_Zmflag(__geo_v.g::geometry) WHEN 1 THEN 'M' WHEN 2 THEN 'Z' WHEN 3 THEN 'ZM' ELSE '' END AS dims FROM (SELECT __v AS g) AS __geo_v) AS __geo WHERE __geo.j IS NOT NULL)), '[]'::json) AS data FROM (SELECT __v FROM "public"."grid_points"("n" => $1::"pg_catalog"."int4") AS __v LIMIT 100) AS __v(__v)
-- args: [3]

-- field: makeSite
SELECT CASE WHEN (__fn.v)::text IS NULL THEN NULL ELSE json_build_object('label', (__fn.v)."label", 'spot', (SELECT CASE WHEN json_array_length(__geo.j->'coordinates') = 0 THEN NULL ELSE json_build_object('x', __geo.j->'coordinates'->0, 'y', __geo.j->'coordinates'->1, 'srid', __geo.srid) END FROM (SELECT ST_AsGeoJSON(__geo_v.g)::json AS j, ST_SRID(__geo_v.g) AS srid FROM (SELECT (__fn.v)."spot" AS g) AS __geo_v) AS __geo WHERE __geo.j IS NOT NULL), 'extent', (SELECT CASE WHEN (__geo.j->>'type') IN ('Point', 'LineString', 'Polygon', 'MultiPoint', 'MultiLineString', 'MultiPolygon', 'GeometryCollection') THEN CASE WHEN 'Geography' || (__geo.j->>'type') || __geo.dims IN ('GeographyPoint', 'GeographyPointM', 'GeographyPointZ', 'GeographyPointZM') THEN CASE WHEN json_array_length(__geo.j->'coordinates') = 0 THEN NULL ELSE json_build_object('__typename', 'Geography' || (__geo.j->>'type') || __geo.dims, 'srid', __geo.srid) END ELSE json_build_object('__typename', 'Geography' || (__geo.j->>'type') || __geo.dims, 'srid', __geo.srid) END END FROM (SELECT ST_AsGeoJSON(__geo_v.g)::json AS j, ST_SRID(__geo_v.g) AS srid, CASE ST_Zmflag(__geo_v.g::geometry) WHEN 1 THEN 'M' WHEN 2 THEN 'Z' WHEN 3 THEN 'ZM' ELSE '' END AS dims FROM (SELECT (__fn.v)."extent" AS g) AS __geo_v) AS __geo WHERE __geo.j IS NOT NULL)) END AS data FROM (SELECT "public"."make_site"("label" => $1::"pg_catalog"."text") AS v) AS __fn
-- args: ["hq"]

